"""Small-group protected aggregate queries.

Pure and request-scoped like the other capabilities: records are only
read from the current payload, the caller's data is never mutated and
nothing is retained between requests. Records are partitioned by the
ordered scalar values found at the ``group_by`` JSON Pointers, and only
groups whose size reaches ``minimum_group_size`` are returned; smaller
groups are suppressed wholesale so their keys, sizes, metrics and
values never leave the process.
"""

from __future__ import annotations

import math
from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any

from .classifier import (
    InvalidRequest,
    InvalidSchema,
    _parse_pointer as _parse_json_pointer,
    _validate_records,
)

_QUANTUM = Decimal("0.000001")

_OPERATIONS = frozenset(("count", "sum", "average"))


class InvalidGroupBy(ValueError):
    """group_by is malformed or does not resolve to scalar values."""


class InvalidMetric(ValueError):
    """A metric definition is malformed or its field is not finite numeric."""


class InvalidThreshold(ValueError):
    """minimum_group_size is not a JSON integer in [2, 1000]."""


def _round6(value: Decimal) -> float:
    """Round a decimal to six places, half up, and emit as a JSON number."""
    return float(value.quantize(_QUANTUM, rounding=ROUND_HALF_UP))


def _parse_pointer(raw: str, error: type[ValueError]) -> tuple[str, ...]:
    try:
        return _parse_json_pointer(raw)
    except InvalidSchema as exc:
        raise error(str(exc)) from exc


def _resolve(record: dict, segments: tuple[str, ...], error: type[ValueError]) -> Any:
    """Resolve a JSON Pointer with strict RFC 6901 array index handling."""
    node: Any = record
    for segment in segments:
        if isinstance(node, dict):
            if segment not in node:
                raise error("every pointer must resolve on every record")
            node = node[segment]
        elif isinstance(node, list):
            if segment == "-" or not segment.isdigit():
                raise error("invalid array index in pointer")
            if segment != "0" and segment[0] == "0":
                raise error("array indices must not have leading zeros")
            index = int(segment)
            if index >= len(node):
                raise error("every pointer must resolve on every record")
            node = node[index]
        else:
            raise error("every pointer must resolve on every record")
    return node


def _group_signature_value(value: Any) -> tuple[int, Any]:
    """Tag a resolved group-by value with JSON equality semantics.

    Types never compare across tags (null != false != 0, strings stay
    distinct) while ints and floats share the numeric tag keyed by their
    decimal value so 1 and 1.0 land in the same group.
    """
    if value is None:
        return (0, 0)
    if isinstance(value, bool):
        return (1, value)
    if isinstance(value, int):
        return (2, Decimal(value))
    if isinstance(value, float):
        if not math.isfinite(value):
            raise InvalidGroupBy("group_by values must be finite scalars")
        return (2, Decimal(str(value)))
    if isinstance(value, str):
        return (3, value)
    raise InvalidGroupBy("group_by pointers must resolve to scalar values")


def _require_finite_number(value: Any) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise InvalidMetric("metric fields must be finite JSON numbers on every record")
    if isinstance(value, float) and not math.isfinite(value):
        raise InvalidMetric("metric fields must be finite JSON numbers on every record")


def _decimal_number(value: Any) -> Decimal:
    if isinstance(value, int):
        return Decimal(value)
    return Decimal(str(value))


def _validate_group_by(raw: Any, records: list[dict]) -> list[tuple[str, ...]]:
    if not isinstance(raw, list):
        raise InvalidGroupBy("group_by must be an array of JSON Pointer strings")
    pointers: list[tuple[str, ...]] = []
    seen: set[str] = set()
    for item in raw:
        if not isinstance(item, str):
            raise InvalidGroupBy("group_by entries must be JSON Pointer strings")
        if item in seen:
            raise InvalidGroupBy("group_by must not contain duplicates")
        seen.add(item)
        pointers.append(_parse_pointer(item, InvalidGroupBy))
    # Every non-empty pointer must resolve to an allowed scalar on every
    # record; the root pointer resolves to the record container and fails.
    for record in records:
        for segments in pointers:
            value = _resolve(record, segments, InvalidGroupBy)
            _group_signature_value(value)
    return pointers


def _validate_metrics(raw: Any, records: list[dict]) -> list[tuple[str, str, tuple[str, ...] | None]]:
    if not isinstance(raw, list) or not raw:
        raise InvalidMetric("metrics must be a non-empty array")
    metrics: list[tuple[str, str, tuple[str, ...] | None]] = []
    names: set[str] = set()
    for item in raw:
        if not isinstance(item, dict):
            raise InvalidMetric("each metric must be an object")
        name = item.get("name")
        if not isinstance(name, str) or not name:
            raise InvalidMetric("each metric needs a unique non-empty name")
        if name in names:
            raise InvalidMetric("metric names must be unique")
        names.add(name)
        operation = item.get("operation")
        if not isinstance(operation, str) or operation not in _OPERATIONS:
            raise InvalidMetric("operation must be count, sum or average")
        if operation == "count":
            if "field" in item:
                raise InvalidMetric("count metrics must not carry a field")
            metrics.append((name, operation, None))
            continue
        field = item.get("field")
        if not isinstance(field, str) or not field or not field.startswith("/"):
            raise InvalidMetric(
                "sum and average metrics require a non-root JSON Pointer field"
            )
        segments = _parse_pointer(field, InvalidMetric)
        if not segments:
            raise InvalidMetric(
                "sum and average metrics require a non-root JSON Pointer field"
            )
        for record in records:
            _require_finite_number(_resolve(record, segments, InvalidMetric))
        metrics.append((name, operation, segments))
    return metrics


def _validate_threshold(raw: Any) -> int:
    # bool is an int subclass in Python, but JSON true/false is not a number.
    if isinstance(raw, bool) or not isinstance(raw, int) or not 2 <= raw <= 1000:
        raise InvalidThreshold("minimum_group_size must be a JSON integer between 2 and 1000")
    return raw


def aggregate_query_request(payload: Any) -> dict:
    """Validate a /v1/query/aggregate payload and run the grouped statistics."""
    records = _validate_records(payload)
    group_pointers = _validate_group_by(payload.get("group_by"), records)
    metrics = _validate_metrics(payload.get("metrics"), records)
    threshold = _validate_threshold(payload.get("minimum_group_size"))

    # Accumulate in first-appearance order; signatures carry JSON equality.
    order: list[tuple[tuple[int, Any], ...]] = []
    groups: dict[tuple, dict[str, Any]] = {}
    with localcontext() as context:
        context.prec = 60
        for record in records:
            values = [_resolve(record, segments, InvalidGroupBy) for segments in group_pointers]
            signature = tuple(_group_signature_value(value) for value in values)
            entry = groups.get(signature)
            if entry is None:
                entry = {
                    "key": values,
                    "size": 0,
                    "sums": [Decimal(0) for _ in metrics],
                }
                groups[signature] = entry
                order.append(signature)
            entry["size"] += 1
            for index, (_name, operation, segments) in enumerate(metrics):
                if segments is not None:
                    value = _resolve(record, segments, InvalidMetric)
                    entry["sums"][index] += _decimal_number(value)

        visible_groups: list[dict] = []
        suppressed_group_count = 0
        for signature in order:
            entry = groups[signature]
            size = entry["size"]
            if size < threshold:
                # Nothing about a suppressed group is exposed.
                suppressed_group_count += 1
                continue
            metric_values: dict[str, Any] = {}
            for index, (name, operation, _segments) in enumerate(metrics):
                if operation == "count":
                    metric_values[name] = size
                elif operation == "sum":
                    metric_values[name] = _round6(entry["sums"][index])
                else:
                    metric_values[name] = _round6(entry["sums"][index] / Decimal(size))
            visible_groups.append(
                {"key": entry["key"], "size": size, "metrics": metric_values}
            )

    return {"groups": visible_groups, "suppressed_group_count": suppressed_group_count}

"""Core service surface for PrivaCare.

Later work adds the real capabilities described in README.md behind this
module; keep the public surface here backward compatible.
"""

from __future__ import annotations

from typing import Any

from . import __version__
from .access import access_evaluate_request
from .aggregate import aggregate_query_request
from .audit import audit_chain_request, audit_verify_request
from .classifier import classify_request
from .compliance import transfer_evaluate_request
from .consent import consent_evaluate_request
from .deidentifier import deidentify_request
from .encryption import decrypt_request, encrypt_request, rotate_request
from .lineage import trace_lineage_request
from .pseudonymizer import pseudonymize_request
from .risk import reidentification_risk_request


class Service:
    """Health reporting, classification, de-identification, risk, consent."""

    name = "privacare"
    version = __version__

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def classify(self, payload: Any) -> list[dict]:
        """Classify sensitive fields in a /v1/classify request payload."""
        return classify_request(payload)

    def deidentify(self, payload: Any) -> list[dict]:
        """De-identify records in a /v1/deidentify request payload."""
        return deidentify_request(payload)

    def pseudonymize(self, payload: Any) -> list[dict]:
        """Pseudonymize records in a /v1/pseudonymize request payload."""
        return pseudonymize_request(payload)

    def reidentification_risk(self, payload: Any) -> dict:
        """Measure k-anonymity re-identification risk in a request payload."""
        return reidentification_risk_request(payload)

    def evaluate_consent(self, payload: Any) -> list[dict]:
        """Evaluate accesses against consents in a /v1/consent/evaluate payload."""
        return consent_evaluate_request(payload)

    def evaluate_access(self, payload: Any) -> list[dict]:
        """Evaluate accesses against grants in a /v1/access/evaluate payload."""
        return access_evaluate_request(payload)

    def audit_chain(self, payload: Any) -> dict:
        """Build a tamper-evident evidence chain for a /v1/audit/chain payload."""
        return audit_chain_request(payload)

    def audit_verify(self, payload: Any) -> dict:
        """Recompute and check an evidence chain for a /v1/audit/verify payload."""
        return audit_verify_request(payload)

    def trace_lineage(self, payload: Any) -> dict:
        """Trace upstream/downstream dataset lineage for a /v1/lineage/trace payload."""
        return trace_lineage_request(payload)

    def encrypt(self, payload: Any) -> list[dict]:
        """Encrypt record fields for a /v1/encryption/encrypt payload."""
        return encrypt_request(payload)

    def decrypt(self, payload: Any) -> list[dict]:
        """Decrypt record envelopes for a /v1/encryption/decrypt payload."""
        return decrypt_request(payload)

    def rotate_encryption(self, payload: Any) -> list[dict]:
        """Re-encrypt record envelopes for a /v1/encryption/rotate payload."""
        return rotate_request(payload)

    def aggregate_query(self, payload: Any) -> dict:
        """Run a small-group protected /v1/query/aggregate payload."""
        return aggregate_query_request(payload)

    def evaluate_transfer(self, payload: Any) -> list[dict]:
        """Evaluate transfers against rules in a /v1/compliance/transfer/evaluate payload."""
        return transfer_evaluate_request(payload)

"""Deterministic, request-scoped pseudonymization for medical records.

Pseudonyms preserve cross-record linkage without retaining any mapping:
the token for a leaf is an HMAC-SHA256 of the original value under the
request secret, bound to the key version, a context and the leaf's
canonical JSON Pointer. Everything is derived from the current request
only — the caller's data is never mutated, no record, key or mapping is
kept between requests, and identical inputs always produce identical
pseudonyms.
"""

from __future__ import annotations

import base64
import binascii
import copy
import hashlib
import hmac
import re
import struct
from typing import Any

from .classifier import InvalidRequest, _pointer, _validate_records

#: Context used when the caller does not supply one.
DEFAULT_CONTEXT = "privacare.pseudonymize.v1"

_BASE64URL_RE = re.compile(r"^[A-Za-z0-9_-]+$")


class InvalidFields(ValueError):
    """The fields array or one of its pointer targets is malformed."""


class InvalidKey(ValueError):
    """The key_id or secret is malformed."""


class InvalidContext(ValueError):
    """The context is malformed."""


def _decode_secret(raw: Any) -> bytes:
    """Validate an unpadded base64url string decoding to at least 32 bytes."""
    if not isinstance(raw, str) or not _BASE64URL_RE.fullmatch(raw):
        raise InvalidKey("secret must be an unpadded base64url string")
    # A length of 4n+1 cannot occur in valid (unpadded) base64.
    if len(raw) % 4 == 1:
        raise InvalidKey("secret must be an unpadded base64url string")
    padded = raw + "=" * (-len(raw) % 4)
    try:
        key = base64.urlsafe_b64decode(padded.encode("ascii"))
    except (binascii.Error, ValueError):
        raise InvalidKey("secret must be an unpadded base64url string") from None
    if len(key) < 32:
        raise InvalidKey("secret must decode to at least 32 bytes")
    return key


def _validate_key_id(raw: Any) -> str:
    if not isinstance(raw, str) or not raw:
        raise InvalidKey("key_id must be a non-empty string")
    return raw


def _validate_context(raw: Any) -> str:
    # Absent (including a literal null) means "use the fixed default"; a
    # present value must be a non-empty string.
    if raw is None:
        return DEFAULT_CONTEXT
    if not isinstance(raw, str) or not raw:
        raise InvalidContext("context must be a non-empty string")
    return raw


def _validate_fields(raw: Any) -> list[tuple[str, ...]]:
    if not isinstance(raw, list) or not raw:
        raise InvalidFields("fields must be a non-empty array of JSON Pointer strings")
    pointers: list[tuple[str, ...]] = []
    seen: set[str] = set()
    for item in raw:
        if not isinstance(item, str) or not item.startswith("/"):
            raise InvalidFields("each field must be a JSON Pointer string starting with '/'")
        segments: list[str] = []
        for part in item.split("/")[1:]:
            out: list[str] = []
            i = 0
            while i < len(part):
                ch = part[i]
                if ch == "~":
                    nxt = part[i + 1] if i + 1 < len(part) else ""
                    if nxt == "0":
                        out.append("~")
                    elif nxt == "1":
                        out.append("/")
                    else:
                        raise InvalidFields("invalid '~' escape in JSON pointer")
                    i += 2
                else:
                    out.append(ch)
                    i += 1
            segments.append("".join(out))
        if item in seen:
            raise InvalidFields("fields must not contain duplicates")
        seen.add(item)
        pointers.append(tuple(segments))
    return pointers


def _resolve_leaf(record: dict, segments: tuple[str, ...]) -> str:
    """Resolve a JSON Pointer to a non-empty string leaf."""
    node: Any = record
    for depth, segment in enumerate(segments):
        last = depth == len(segments) - 1
        if isinstance(node, dict):
            if segment not in node:
                raise InvalidFields("every field pointer must resolve on every record")
            node = node[segment]
        elif isinstance(node, list):
            # RFC 6901: "-" never resolves, only "0" may start with '0'.
            if segment == "-" or not segment.isdigit():
                raise InvalidFields("invalid array index in field pointer")
            if segment != "0" and segment[0] == "0":
                raise InvalidFields("array indices must not have leading zeros")
            index = int(segment)
            if index >= len(node):
                raise InvalidFields("every field pointer must resolve on every record")
            node = node[index]
        else:
            raise InvalidFields("every field pointer must resolve on every record")
        if last and (not isinstance(node, str) or not node):
            raise InvalidFields("field pointers must resolve to non-empty string leaves")
    return node


def _token(key: bytes, key_id: str, context: str, path: str, value: str) -> str:
    """Derive the 43-char unpadded base64url token for one value."""
    parts = (key_id, context, path, value)
    message = b"pv1" + b"".join(
        struct.pack(">I", len(part.encode("utf-8"))) + part.encode("utf-8") for part in parts
    )
    digest = hmac.new(key, message, hashlib.sha256).digest()
    return base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")


def _set_leaf(node: Any, segments: tuple[str, ...], value: str) -> None:
    for segment in segments[:-1]:
        node = node[int(segment)] if isinstance(node, list) else node[segment]
    last = segments[-1]
    if isinstance(node, list):
        node[int(last)] = value
    else:
        node[last] = value


def pseudonymize_request(payload: Any) -> list[dict]:
    """Validate a /v1/pseudonymize payload and pseudonymize every record."""
    records = _validate_records(payload)
    pointers = _validate_fields(payload.get("fields"))
    # Every pointer must resolve to a non-empty string leaf on every record
    # before anything is transformed — failures never return partial output.
    for record in records:
        for segments in pointers:
            _resolve_leaf(record, segments)
    key_id = _validate_key_id(payload.get("key_id"))
    key = _decode_secret(payload.get("secret"))
    context = _validate_context(payload.get("context"))

    paths = [_pointer(segments) for segments in pointers]
    results: list[dict] = []
    for index, record in enumerate(records):
        transformed = copy.deepcopy(record)
        token_cache: dict[tuple[str, str], str] = {}
        for segments, path in zip(pointers, paths):
            original = _resolve_leaf(record, segments)
            cache_key = (path, original)
            token = token_cache.get(cache_key)
            if token is None:
                token = _token(key, key_id, context, path, original)
                token_cache[cache_key] = token
            _set_leaf(transformed, segments, f"pv1.{key_id}.{token}")
        transformations = [{"path": path, "key_id": key_id} for path in sorted(paths)]
        results.append(
            {"index": index, "record": transformed, "transformations": transformations}
        )
    return results

import http.client
import json
import threading
import unittest
from http.server import ThreadingHTTPServer

from privacare import __version__
from privacare.server import Handler


class HttpTestBase(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.httpd = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        cls.port = cls.httpd.server_address[1]
        cls.thread = threading.Thread(target=cls.httpd.serve_forever, daemon=True)
        cls.thread.start()

    @classmethod
    def tearDownClass(cls):
        cls.httpd.shutdown()
        cls.httpd.server_close()
        cls.thread.join()

    def request(self, method, path, body=None, content_type=None):
        conn = http.client.HTTPConnection("127.0.0.1", self.port, timeout=5)
        headers = {}
        if content_type is not None:
            headers["Content-Type"] = content_type
        conn.request(method, path, body=body, headers=headers)
        resp = conn.getresponse()
        raw = resp.read()
        conn.close()
        return resp.status, json.loads(raw)


class ClassifyHttpTest(HttpTestBase):
    def post(self, payload, content_type="application/json"):
        body = payload if isinstance(payload, (str, bytes)) else json.dumps(payload)
        return self.request("POST", "/v1/classify", body=body, content_type=content_type)

    def test_healthz_unchanged(self):
        status, payload = self.request("GET", "/healthz")
        self.assertEqual(status, 200)
        self.assertEqual(
            payload,
            {"status": "ok", "service": "privacare", "version": __version__},
        )

    def test_unknown_path_404(self):
        status, payload = self.request("GET", "/nope")
        self.assertEqual(status, 404)
        self.assertEqual(payload["error"]["code"], "not_found")

    def test_classify_happy_path(self):
        status, payload = self.post(
            {
                "records": [
                    {"name": "张三", "contact": {"phone": "13800138000"}},
                    {"note": "nothing"},
                ],
                "schema": {"/note": "clinical"},
            }
        )
        self.assertEqual(status, 200)
        results = payload["results"]
        self.assertEqual([r["index"] for r in results], [0, 1])
        fields = {f["path"]: f for f in results[0]["fields"]}
        self.assertEqual(fields["/name"]["categories"], ["direct_identifier"])
        self.assertEqual(fields["/contact/phone"]["categories"], ["contact"])
        self.assertEqual(fields["/contact/phone"]["sources"], ["field_name", "value"])
        self.assertEqual(
            results[1]["fields"],
            [{"categories": ["clinical"], "path": "/note", "sources": ["schema"]}],
        )
        # 原始值不得回显
        self.assertNotIn("张三", json.dumps(payload, ensure_ascii=False))
        self.assertNotIn("13800138000", json.dumps(payload))

    def test_unsupported_media_type(self):
        status, payload = self.post({"records": [{}]}, content_type="text/plain")
        self.assertEqual(status, 415)
        self.assertEqual(payload["error"]["code"], "unsupported_media_type")

    def test_missing_content_type(self):
        status, payload = self.request("POST", "/v1/classify", body="{}")
        self.assertEqual(status, 415)
        self.assertEqual(payload["error"]["code"], "unsupported_media_type")

    def test_invalid_json(self):
        status, payload = self.post("{not json")
        self.assertEqual(status, 400)
        self.assertEqual(payload["error"]["code"], "invalid_json")

    def test_invalid_request(self):
        for body in ("[]", "{}", '{"records": []}', '{"records": [1]}'):
            with self.subTest(body=body):
                status, payload = self.post(body)
                self.assertEqual(status, 422)
                self.assertEqual(payload["error"]["code"], "invalid_request")

    def test_invalid_schema(self):
        status, payload = self.post({"records": [{}], "schema": {"/x": "nope"}})
        self.assertEqual(status, 422)
        self.assertEqual(payload["error"]["code"], "invalid_schema")

    def test_method_not_allowed(self):
        for method in ("GET", "PUT", "DELETE", "PATCH"):
            with self.subTest(method=method):
                status, payload = self.request(method, "/v1/classify")
                self.assertEqual(status, 405)
                self.assertEqual(payload["error"]["code"], "method_not_allowed")

    def test_error_body_has_no_sensitive_values(self):
        secret = "11010519491231002X"
        status, payload = self.post({"records": [{"id": secret}], "schema": "bad"})
        self.assertEqual(status, 422)
        self.assertNotIn(secret, json.dumps(payload))


if __name__ == "__main__":
    unittest.main()

